WITH lines AS (SELECT id, host, level, status_code, key, v FROM app_logs LATERAL VIEW EXPLODE(context) t AS key, v), base AS (SELECT *, CASE WHEN status_code >= 444 THEN 'High' WHEN status_code >= 243 THEN 'Medium' ELSE 'Low' END status_code_tier FROM lines WHERE key IS NOT NULL AND key = 'region'), with_windows AS (SELECT *, SUM(status_code) OVER (PARTITION BY host ORDER BY status_code ASC, id ASC, key ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_status_code, MAX(status_code) OVER (PARTITION BY key) key_max_status_code, SUM(status_code) OVER (ORDER BY status_code ASC, id ASC, key ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_status_code_2 FROM base), valid AS (SELECT id, level, status_code, key, v, status_code_tier, running_status_code, key_max_status_code, status_code * key_max_status_code status_code_times_key_max_status_code, status_code * running_status_code status_code_times_running_status_code FROM with_windows WHERE host = 'h1') SELECT CASE WHEN key_max_status_code >= 441 THEN 'HIGH' ELSE 'LOW' END AS key_max_status_code_tier, COUNT(*) AS row_count, COUNT(*) AS num_rows, SORT_ARRAY(COLLECT_SET(level)) AS level_list, GROUPING_ID() AS gid FROM valid GROUP BY ROLLUP (CASE WHEN key_max_status_code >= 441 THEN 'HIGH' ELSE 'LOW' END) HAVING row_count >= 1 ORDER BY row_count DESC;
